interface.definition:
a!localVariables(
  local!fiscalYear: #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3953700"(),
  local!fiscalYearDisplay: right(local!fiscalYear,2),
  local!nominations: #"_a-0000e6bc-0703-8000-9bf8-011c48011c48_3461738"(
    fiscalYear: local!fiscalYear,
    columns: {"positionTypeId","subPositionTypeId"},
    notCancelled: true,
    isActive: true
  ),
  local!nominationCoreCount: length(wherecontains(
    #"_a-0000e6c6-37ec-8000-9bfb-011c48011c48_3596692",
    tointeger(index(local!nominations.data,"positionTypeId",{}))
  )),
  local!nominationRotationalCount: length(wherecontains(
    #"_a-0000e6c6-37ec-8000-9bfb-011c48011c48_3596699",
    tointeger(index(local!nominations.data,"positionTypeId",{}))
  )),
  local!nominationRotationalAskCount: length(wherecontains(
    {
      #"_a-0000e723-cc8a-8000-9c0d-011c48011c48_4454622",
      #"_a-0000e723-cc8a-8000-9c0d-011c48011c48_4454629"
    },
    tointeger(index(local!nominations.data,"subPositionTypeId",{}))
  )),
  local!nominationOtherRotationalCount: local!nominationRotationalCount - local!nominationRotationalAskCount,
  local!rotationalAskPlan: sum(tointeger(index(#"_a-0000e825-ace1-8000-9c24-011c48011c48_6906867"(
    fiscalYear: local!fiscalYear
  ),"plan",{}))),
  local!coreAsks: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3235974"(
    fiscalYear: local!fiscalYear,
    isCompleted: true,
    isActive: true,
    returnCDT: true
  ),
  local!latestVersionCoreAsks: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6753074"(local!coreAsks),
  #"SYSTEM_SYSRULES_columnsLayout"(
    alignVertical: "BOTTOM",
    spacing: "DENSE",
    columns: {
      #"SYSTEM_SYSRULES_columnLayout"(
        width: "NARROW",
        contents: #"SYSTEM_SYSRULES_cardLayout"(
          style: "ACCENT",
          contents: {
            #"SYSTEM_SYSRULES_richTextDisplayField"(
              labelPosition: "COLLAPSED",
              value: {
                #"SYSTEM_SYSRULES_richTextItem_v1"(text: count(ri!taskStatuses), size: "LARGE_PLUS")
              },
              align: "CENTER"
            ),
            #"SYSTEM_SYSRULES_richTextDisplayField"(
              labelPosition: "COLLAPSED",
              value: {
                #"SYSTEM_SYSRULES_richTextIcon"(icon: "folder-open-o", size: "MEDIUM"),
                " ",
                #"SYSTEM_SYSRULES_richTextItem_v1"(
                  text: "Open Tasks",
                  color: "ACCENT",
                  size: "MEDIUM"
                )
              },
              align: "CENTER"
            )
          }
        )
      ),
      #"SYSTEM_SYSRULES_columnLayout"(
        contents: #"SYSTEM_SYSRULES_cardLayout"(
          style: "ACCENT",
          contents: #"SYSTEM_SYSRULES_columnsLayout"(
            columns: {
              #"SYSTEM_SYSRULES_columnLayout"(
                contents: {
                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                    labelPosition: "COLLAPSED",
                    value: {
                      #"SYSTEM_SYSRULES_richTextItem_v1"(
                        text: local!nominationRotationalAskCount,
                        size: "LARGE_PLUS"
                      )
                    },
                    align: "CENTER"
                  ),
                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                    labelPosition: "COLLAPSED",
                    value: {
                      #"SYSTEM_SYSRULES_richTextItem_v1"(
                        text: "Traditional/ Early Career Rot.",
                        size: "MEDIUM"
                      )
                    },
                    align: "CENTER"
                  )
                }
              ),
              #"SYSTEM_SYSRULES_columnLayout"(
                contents: {
                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                    labelPosition: "COLLAPSED",
                    value: {
                      #"SYSTEM_SYSRULES_richTextItem_v1"(
                        text: local!rotationalAskPlan,
                        size: "LARGE_PLUS"
                      )
                    },
                    align: "CENTER"
                  ),
                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                    labelPosition: "COLLAPSED",
                    value: {
                      #"SYSTEM_SYSRULES_richTextIcon"(icon: "list-alt", size: "MEDIUM"),
                      " ",
                      #"SYSTEM_SYSRULES_richTextItem_v1"(
                        text: "FY"&local!fiscalYearDisplay&" Rotational ASKs",
                        size: "MEDIUM"
                      )
                    },
                    align: "CENTER"
                  )
                }
              ),
              #"SYSTEM_SYSRULES_columnLayout"(
                contents: {
                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                    labelPosition: "COLLAPSED",
                    value: {
                      #"SYSTEM_SYSRULES_richTextItem_v1"(
                        text: local!nominationOtherRotationalCount, 
                        size: "LARGE_PLUS"
                      )
                    },
                    align: "CENTER"
                  ),
                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                    labelPosition: "COLLAPSED",
                    value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                      text: "Non-Traditional/ Other Rot.",
                      color: "ACCENT",
                      size: "MEDIUM"
                    ),
                    align: "CENTER"
                  )
                }
              )
            }
          )
        )
      ),
      #"SYSTEM_SYSRULES_columnLayout"(
        width: if(
          #"SYSTEM_SYSRULES_isPageWidth"({"DESKTOP_WIDE"}),
          "MEDIUM_PLUS",
          if(
            #"SYSTEM_SYSRULES_isPageWidth"({"DESKTOP_NARROW"}),
            "NARROW_PLUS",
            "AUTO"
          )
        ),
        contents: #"SYSTEM_SYSRULES_cardLayout"(
          style: "ACCENT",
          contents: #"SYSTEM_SYSRULES_columnsLayout"(
            columns: {
              #"SYSTEM_SYSRULES_columnLayout"(
                contents: {
                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                    labelPosition: "COLLAPSED",
                    value: {
                      #"SYSTEM_SYSRULES_richTextItem_v1"(
                        text: local!nominationCoreCount, 
                        size: "LARGE_PLUS"
                      )
                    },
                    align: "CENTER"
                  ),
                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                    labelPosition: "COLLAPSED",
                    value: {
                      #"SYSTEM_SYSRULES_richTextItem_v1"(
                        text: "Core Partner/ Professional",
                        color: "ACCENT",
                        size: "MEDIUM"
                      )
                    },
                    align: "CENTER"
                  )
                }
              ),
              #"SYSTEM_SYSRULES_columnLayout"(
                contents: {
                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                    labelPosition: "COLLAPSED",
                    value: {
                      #"SYSTEM_SYSRULES_richTextItem_v1"(
                        text:sum({index(local!latestVersionCoreAsks,"headCountAmount",0)}), 
                        size: "LARGE_PLUS"
                      )
                    },
                    align: "CENTER"
                  ),
                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                    labelPosition: "COLLAPSED",
                    value: {
                      #"SYSTEM_SYSRULES_richTextIcon"(icon: "list-alt", size: "MEDIUM"),
                      " ",
                      #"SYSTEM_SYSRULES_richTextItem_v1"(
                        text: "FY"&local!fiscalYearDisplay&" Core ASKS",
                        color: "ACCENT",
                        size: "MEDIUM"
                      )
                    },
                    align: "CENTER"
                  )
                }
              )
            }
          )
        )
      ),
      #"SYSTEM_SYSRULES_columnLayout"(
        width: "NARROW",
        contents: #"SYSTEM_SYSRULES_cardLayout"(
          style: "ACCENT",
          contents: {
            #"SYSTEM_SYSRULES_richTextDisplayField"(
            labelPosition: "COLLAPSED",
            value: {
              #"SYSTEM_SYSRULES_richTextItem_v1"(
                text: index(local!nominations,"totalCount",0), 
                size: "LARGE_PLUS"
              ),
            },
            align: "CENTER"
          ),
          #"SYSTEM_SYSRULES_richTextDisplayField"(
            labelPosition: "COLLAPSED",
            value: {
              #"SYSTEM_SYSRULES_richTextIcon"(icon: "user-plus", size: "MEDIUM"),
              " ",
              #"SYSTEM_SYSRULES_richTextItem_v1"(
                text: "Total Nominations",
                color: "ACCENT",
                size: "MEDIUM"
              )
            },
            align: "CENTER"
          )
          }
        )
      )
    },
    stackWhen: {
      "PHONE",
      "TABLET_PORTRAIT",
      "TABLET_LANDSCAPE"
    },
    marginBelow: "MORE",
    showWhen: isusermemberofgroups(
      loggedInUser(),
      #"_a-0000e6b8-3009-8000-9bf7-011c48011c48_3443785"
    )
  )
)
